from lib import *
S = SS('h27')
steps = [
    step("加字段(新→旧):新版本多了 extra = 4。新版本写出 20 字节;旧版本读到 {msg=hello, n=7},外加 11 字节“未知字段”(2209e696b0e5ad97e6aeb5)——不认识但没有丢。旧版本原样写回(仍是 20 字节),新版本再读又得到 extra=新字段。真实 gRPC:新版客户端(带 extra)调用用旧版生成代码的服务端,服务端把收到的请求原样放进响应,新版客户端解出 {msg=hi, n=1, extra=新字段}——经过旧服务端,新字段还在。所以“加字段”是安全的,而且经过老的中间服务也不会丢(前提是中间服务整条消息解析再序列化,不是只挑几个字段重新拼)。", t=tl(S(1)), done=lidx(S(1), '真实 gRPC'), mark=lidx(S(1), '新版本写出'), b=bars([['新版本写出的字节', 20, '20'], ['旧版本保留的未知字段字节', 11, '11']], 22, mark=[0], done=[1]), kv=KV([['旧读新', '看不见新字段,但保留 11 字节'], ['旧写回', '原样 20 字节'], ['经过旧服务端往返', 'extra 还在']], ['经过旧服务端往返'])),
    step("改字段名(name → full_name,编号不变):二进制完全兼容——旧写 0a05616c696365,新版本读到 full_name=alice,因为线上只有编号没有名字。但 JSON 不兼容:旧版写 {\"name\":\"alice\"},新版 protojson 解析报错 unknown field \"name\"。如果有 JSON 的消费方(网关、日志、前端),改名就是破坏性的(第 29 篇)。", t=tl(S(2)), done=lidx(S(2), 'JSON:'), mark=lidx(S(2), '二进制:'), b=bars([['二进制是否兼容(1=兼容)', 1, '兼容'], ['JSON 是否兼容(0=不兼容)', 0, 'unknown field']], 1.2, mark=[1], done=[0]), kv=KV([['二进制', '只看编号,改名兼容'], ['JSON', '按名字,改名报 unknown field'], ['结论', '有 JSON 消费方时别改名']], ['结论'])),
    step("改字段编号(n 从 2 改成 5):旧版本写 n=42(线上 0a0178102a),新版本读到 {msg=x},n 没了,变成 2 字节未知字段(102a)。不报错,值悄悄丢了。编号一旦发布就不能改,要换就新加字段、再慢慢迁移。", t=tl(S(3)), done=lidx(S(3), '旧写 n=42'), mark=lidx(S(3), '旧写 n=42'), b=bars([['写入的 n', 42, '42'], ['新版本读到的 n(丢了)', 0, '0']], 45, mark=[0], done=[1]), kv=KV([['旧写', 'n = 42,编号 2'], ['新读', '编号 2 不认识,n 为 0'], ['报错', '没有,悄悄丢']], ['报错'])),
    step("改字段类型(写入方写 int32 值,读取方换成另一个类型读同一个编号):int32 → int64:读到 5,值为 -1 时读到 -1,兼容;int32 → sint32:5 读成 -3,-1 读成 -2147483648,同样是 varint 却用了不同的编码(zigzag),值悄悄错了;int32 → bool:5 读成 true;int32 → string 和 int32 → fixed32:线上类型(wire type)对不上,读成空、变成 2 字节未知字段;string → bytes:兼容(都是长度前缀)。看起来能解析的改动不一定是对的:只有 wire type 和编码都相同的类型才能放心改。", t=tl(S(4)), done=lidx(S(4), 'string → bytes'), mark=lidx(S(4), 'int32 → sint32  '), b=bars([['写入的 int32 值', 5, '5'], ['读成 sint32 得到的值', 3, '-3(绝对值 3)']], 6, mark=[1], done=[0]), kv=KV([['int32 → int64', '兼容'], ['int32 → sint32', '能读但值错(5 → -3)'], ['int32 → string / fixed32', 'wire type 不同,读成未知字段']], ['int32 → sint32'])),
    step("删字段后把编号复用成别的类型:旧客户端仍在发 n = 42(int32,编号 2),新版本把编号 2 改成 string label:新版本读到 {msg=x},编号 2 的数据变成 2 字节未知字段,类型对不上被忽略。如果复用成另一个 int32 字段(含义完全不同):读到 label=42——旧字段的值被当成新字段的含义,没有任何报错。所以删掉字段后要 reserved 掉编号(和名字),永远不复用。", t=tl(S(5)), done=lidx(S(5), '如果复用成另一个 int32'), mark=lidx(S(5), '旧写 0a0178102a'), b=bars([['复用成 string:读到的值(丢弃)', 0, '丢弃'], ['复用成 int32:读到的 label', 42, '42']], 45, mark=[1], done=[0]), kv=KV([['复用成 string', '线上类型不同,忽略'], ['复用成 int32', '读到 label=42(含义错位)'], ['做法', 'reserved 编号,不复用']], ['做法'])),
    step("枚举加新值:新版本发出枚举值 3(线上 0803),旧版本的枚举只定义了 0、1、2:旧版本读到的是未知枚举值 3(proto3 的枚举是开放的,数值保留、没有报错);旧版本原样写回,新版本再读还是 RETRY。旧代码里 switch 要有 default 分支,把没见过的值按“未知”处理,而不是当成 0 或者 panic。", t=tl(S(6)), done=lidx(S(6), '旧版本原样写回'), mark=lidx(S(6), '新写 0803'), b=bars([['新枚举值', 3, '3'], ['旧版本能识别的最大值', 2, '2']], 4, mark=[0], done=[1]), kv=KV([['旧版本读', '未知枚举值 3,保留数值'], ['写回再读', '新版本还是 RETRY'], ['要求', '旧代码要有 default 分支']], ['要求'])),
    step("标量 ↔ repeated:标量 5 → 读成 repeated:线上 1005,读到 nums=[5],兼容;repeated [1 2 3](proto3 默认 packed,线上 1203010203)→ 读成标量:读到空,变成 5 字节未知字段——packed 的 wire type 是长度前缀,和标量的 varint 对不上。所以“标量改成 repeated”能兼容旧发送方,“repeated 改成标量”不兼容。", t=tl(S(7)), done=lidx(S(7), 'repeated [1 2 3] → 标量'), mark=lidx(S(7), '标量 5 → repeated'), b=bars([['标量→repeated 读到的元素数', 1, '1'], ['packed repeated→标量 读到的值数', 0, '0']], 2, mark=[0], done=[1]), kv=KV([['标量 → repeated', '兼容,读到 [5]'], ['packed repeated → 标量', '读不到,变成未知字段'], ['方向', '只能标量改成 repeated']], ['方向'])),
]
A = mkarth('h27', 27, 'gRPC,protobuf,向后兼容,字段编号,未知字段,枚举,wire type,Go,真实验证,动画演示',
    '实测 protobuf 的兼容性:加字段安全且经过旧服务端不丢;改名二进制兼容但 JSON 破坏;改编号悄悄丢值;int32 改 sint32 值错位;复用编号不报错但含义错位;枚举新值保留数值;标量改 repeated 单向兼容。',
    '服务升级时,新旧客户端和服务端混着跑,哪些改动是安全的?哪些会悄悄把数据弄错?这篇用动态构造的两个版本的 .proto,在字节层面逐项对比,并用真实 gRPC 验证了“加字段经过旧服务端不丢”。',
    [('11 字节', '旧版本不认识新字段时保留的未知字段,经过旧服务端再回到新版本时仍可解出'), ('5 → -3', 'int32 的 5 被读成 sint32 的值——类型能解析,但值悄悄变了'), ('unknown field "name"', '只改字段名,二进制兼容,但 JSON 解析会报这个错')],
    [('线上只有编号', '<p>protobuf 二进制只写字段编号和值,不写名字。编号和线上类型(wire type)决定兼容性,名字只影响 JSON 与代码。</p>'),
     ('加字段', '<p>安全:旧版本会保留不认识的字段,转发或写回时原样带出,经过旧服务端也不丢。</p>'),
     ('改名', '<p>二进制兼容,但 JSON 按名字,改名对 JSON 消费方(网关、日志、前端)是破坏性的。</p>'),
     ('改编号与复用编号', '<p>改编号或复用已删字段的编号,会悄悄丢数据或读到含义错位的值,不一定有报错。删字段后要 reserved 编号。</p>'),
     ('改类型', '<p>编码相同的类型可以互改(int32/int64、string/bytes);换成 sint32、bool、fixed32、string 会读出错值或变成未知字段。</p>'),
     ('枚举', '<p>proto3 的枚举是开放的,新值保留数值,旧代码要有 default 分支。</p>'),
     ('标量与 repeated', '<p>标量可以改成 repeated(旧发送方的数据仍可读),反过来不行(packed 的 repeated 读不进标量)。</p>')],
    steps,
    [ENV_H + '。两个版本的“.proto”是用 protodesc 在代码里构造的描述符(每个都在独立的 package),消息用 dynamicpb;“线上”的十六进制是 proto.Marshal 的真实输出;第一节的 gRPC 往返用旧版生成代码的服务端(把请求原样序列化放进响应)与带 extra 字段的动态消息客户端;所有结果都来自 protobuf-go(Go 实现)',
     '没有验证:proto2 与 required 字段;oneof 的兼容规则;map 字段;嵌套消息改成不同类型;其它语言的 protobuf 实现(Java、Python 对未知字段和未知枚举的处理有差别);protojson 的 DiscardUnknown 选项;golang/protobuf 老版本;buf breaking 等工具'],
    '兼容性')
